<?php $mostrarIdentidad=!$esEstudiante&&$vista!=='estudiante';?><div class="card-body p-0"><?php if(empty($calificaciones)):?><div class="empty-state my-4"><i class="fas fa-chart-line"></i><h4>Todavía no hay calificaciones</h4></div><?php else:?><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><?php if($mostrarIdentidad):?><th>Estudiante</th><th>Profesor</th><?php endif;?><th>Fecha</th><th>Curso</th><th>Materia</th><th>Actividad o evaluación</th><th>Nota</th></tr></thead><tbody><?php foreach($calificaciones as $item):$esCierre=($item['origen']??'')==='Cierre de período';$texto=trim(($item['apellidoUsuario']??'').' '.($item['nombreUsuario']??'').' '.($item['docente']??'').' '.($item['curso']??'').' '.($item['materia']??'').' '.($item['actividad']??''));?><tr data-grade-row data-search="<?php echo $e($texto);?>" class="<?php echo $esCierre?'grade-detail-closing':'';?>"><?php if($mostrarIdentidad):?><td><?php echo $e(trim(($item['apellidoUsuario']??'').' '.($item['nombreUsuario']??'')));?></td><td><?php echo $e($item['docente']??'');?></td><?php endif;?><td><?php echo $e($fecha($item['fecha']??''));?></td><td><?php echo $e($item['curso']??'');?></td><td><?php echo $e($item['materia']??'');?></td><td><span class="d-block"><?php echo $e($item['actividad']??'');?></span><small class="text-muted"><?php echo $e($item['origen']??'');?></small></td><td><strong class="<?php echo $esCierre?'grade-result '.(((float)($item['nota']??0)>=7)?'is-approved':'is-failed'):'';?>"><?php echo $e($item['nota']??'');?></strong></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
